import { Api } from './base/api'; // Импорт базового класса API и типа для ответа с элементами списка
export class AuctionAPI extends Api {
    // Конструктор, инициализирует базовый API и CDN для изображений
    constructor(cdn, baseUrl, options) {
        super(baseUrl, options); // Вызывает конструктор базового API
        this.cdn = cdn; // Устанавливает ссылку на CDN
    }
    // Получение одного лота по ID
    getLotItem(id) {
        return this.get(`/lot/${id}`).then((item) => (Object.assign(Object.assign({}, item), { image: this.cdn + item.image })));
    }
    // Получение обновлений для лота по ID
    getLotUpdate(id) {
        return this.get(`/lot/${id}/_auction`).then((data) => data // Возвращает данные обновлений лота
        );
    }
    // Получение списка всех лотов
    getLotList() {
        return this.get('/lot').then((data) => data.items.map((item) => (Object.assign(Object.assign({}, item), { image: this.cdn + item.image }))));
    }
    // Размещение ставки на лот
    placeBid(id, bid) {
        return this.post(`/lot/${id}/_bid`, bid).then((data) => data // Возвращает обновленные данные лота после размещения ставки
        );
    }
    // Сделать заказ на лоты
    orderLots(order) {
        return this.post('/order', order).then((data) => data // Возвращает результат оформления заказа
        );
    }
}
